package io.github.danielhp95.caracole.server.routes.search

import io.github.danielhp95.caracole.server.testing.json
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonNull
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import java.net.URLEncoder
import kotlin.test.assertEquals
import kotlin.test.fail

/**
 * A site turned off (caracole.toml's `enabled = false`: gtptabs.com, MuseScore, harptabs.com, gametabs.net; the
 * phone's [io.github.danielhp95.caracole.server.routes.SearchRoutes.enabled]) is searched no more, and the answer
 * says so as caracole serve's does: `skipped` and `looked` "off in caracole.toml", "…: off", its rows none, an
 * artist's songs on gtptabs.com 0 (search_routes._skipped, _harptabs_left_out, _looked, _gametabs_looked,
 * _gtptabs_songs). The answers below are caracole serve's over the same fixtures with the same caracole.toml.
 */
class SitesOffTest {
    @get:Rule val tmp = TemporaryFolder()

    private data class Asked(val fixture: String, val config: String, val q: String, val expected: String)

    @Test
    fun a_site_turned_off_is_left_out_and_said_to_be() {
        val failures = ArrayList<String>()
        for ((key, asked) in ANSWERS.groupBy { it.fixture to it.config }) {
            val (fixture, config) = key
            val dir = tmp.newFolder("$fixture-${config.replace(' ', '-')}")
            SearchApp(dir, fixture, enabled = CONFIGS.getValue(config)).use { search ->
                for (sql in EXTRA[fixture].orEmpty()) search.app.database.writeBlocking { it.execute(sql) }
                for (a in asked) {
                    val answer = search.app.get("/api/search?q=${URLEncoder.encode(a.q, Charsets.UTF_8)}&box=t")
                    assertEquals(200, answer.status, a.q)
                    difference(Json.parseToJsonElement(a.expected), whereLooked(answer.json.jsonObject))
                        ?.let { failures += "$fixture, $config, \"${a.q}\": $it" }
                }
            }
        }
        if (failures.isNotEmpty()) fail(failures.joinToString("\n"))
    }

    private companion object {
        /** caracole.toml's switches, as the generator wrote them, and the sites they leave on. */
        val CONFIGS = mapOf(
            "all off" to emptySet(),
            "musescore off" to setOf("gtptabs", "harptabs", "gametabs"),
            "all on" to setOf("gtptabs", "musescore", "harptabs", "gametabs"),
        )

        /** Rows the fixtures lack, added as the generator added them: an artist of LaCuerda's on gtptabs.com. */
        val EXTRA = mapOf("lacuerda" to listOf(
            "INSERT INTO gtptabs_index (path, artist_path, artist_key, title_key, base_key, sitemap) VALUES " +
                "('tabs/5/estopa/como-camaron.html', 'tabs/5/estopa.html', 'estopa', 'como-camaron', " +
                "'como-camaron', '1')",
        ))

        private fun names(rows: JsonElement): JsonArray = JsonArray(rows.jsonArray.map { r ->
            val row = r.jsonObject
            JsonArray(listOf(row.getValue("source"), row["artist"] ?: JsonNull, row.getValue("title")))
        })

        private fun counted(rows: JsonElement): JsonArray = JsonArray(rows.jsonArray.map { a ->
            JsonArray(listOf(a.jsonObject.getValue("artist"), a.jsonObject.getValue("gtptabs")))
        })

        /** What the test compares of an answer: where it looked and why, each site's rows by their names, and each
         * artist's songs on gtptabs.com. */
        fun whereLooked(answer: JsonObject): JsonObject = JsonObject(linkedMapOf(
            "skipped" to answer.getValue("skipped"), "partial" to answer.getValue("partial"),
            "looked" to answer.getValue("looked"),
            "gtptabs" to names(answer.getValue("gtptabs")), "musescore" to names(answer.getValue("musescore")),
            "harptabs" to names(answer.getValue("harptabs")), "gametabs" to names(answer.getValue("gametabs")),
            "harptabs_artists" to JsonArray(answer.getValue("harptabs_artists").jsonArray.map {
                it.jsonObject.getValue("artist")
            }),
            "lacuerda_artists" to counted(answer.getValue("lacuerda_artists")),
            "artists" to counted(answer.getValue("artists")),
        ))

